// APU of a recompiled SNES cart: the SPC700 (S-SMP) and the S-DSP running
// inside the cart, clocked against the 65816 the way snes9x clocks them.
//
// SPC700: the 256 opcode bodies and the ALU helpers are a mechanical
// translation of snes9x's bapu SMP core (smp/core/oppseudo_*.cpp,
// smp/algorithms.cpp), generated by scripts/recompile-gen/snes9x-apu.mjs
// into snes9x-apu.json together with the boot ROM (IPL) bytes, which are
// romdev's own clean-room boot ROM (scripts/spc700-ipl, MIT), the same one
// the snes9x core is built with. The resumable
// `opcode_cycle` steps are kept, so an instruction can straddle a CPU sync
// exactly as it does in snes9x. The bus (smp/memory.cpp), timers
// (smp/timing.cpp, smp.hpp Timer<>), SMP::enter/power and the CPU side of
// the ports (apu.cpp S9xAPUExecute / S9xAPUReadPort / S9xAPUWritePort /
// S9xAPUEndScanline) are written here by hand from those files.
//
// S-DSP: blargg's SPC_DSP (snes9x apu/bapu/dsp/SPC_DSP.cpp, sdsp.hpp)
// ported by hand: the 32-phase voice/echo/misc clock, BRR decode, the
// gaussian interpolator (snes9x's default InterpolationMethod 2), the
// ADSR/GAIN envelope with its counter table, noise, pitch modulation, the
// echo FIR and the echo WRITES into ARAM (SeparateEchoBuffer off, the
// libretro default), and the internal/external register pair that makes
// ENDX/ENVX/OUTX lag a write by a clock or two. Its tables come from the
// same generator.
//
// Clocking (apu.cpp): the SMP runs `(15664 * (cpu master clocks since the
// last sync) + remainder) / 328125` clocks every time the 65816 touches a
// port and at the end of every scanline; the DSP runs lazily, when the SMP
// touches $F3 and at the end of every scanline. Positions are master
// clocks into the 1364-clock line, as snes9x's CPU.Cycles.
//
// Plain JS ESM + JSDoc.

import { APUST, AUDIO, AUDIO_FRAMES, RESAMP, RESAMP_SIZE } from "./layout.js";
import apu from "./snes9x-apu.json" with { type: "json" };

/** @type {{iplrom:number[], ops:string[], functions:Record<string,string>, opTemps:number, dsp:{gauss:number[], counterRates:number[], counterOffsets:number[], initialRegs:number[]}}} */
const APU = apu;

// APU state block (APUST + ...).
export const APU_OFF = Object.freeze({
  REGS: 0x0000,      // DSP internal registers (128)
  XREGS: 0x0080,     // DSP external registers (128): what the SMP reads at $F3
  CPUREG: 0x0100,    // CPU->APU port latches (4): what the SMP reads at $F4-$F7
  IPL: 0x0140,       // IPL ROM (64)
  INITREGS: 0x0180,  // DSP power-on external registers (128)
  HIST: 0x0200,      // echo history [16][2] i32
  GAUSS: 0x0400,     // gauss[512] i16
  RATES: 0x0800,     // counter_rates[32] i32
  OFFSETS: 0x0880,   // counter_offsets[32] i32
  VOICES: 0x1000,    // 8 voices x 0x100
  MUTE: 0x17f0,      // SPC_DSP mute_mask: bit i keys voice i off (verification control)
  END: 0x1800,
});
const V = Object.freeze({ BUF: 0, BUFPOS: 0x60, IPOS: 0x64, BRRADDR: 0x68, BRROFF: 0x6C, KOND: 0x70, EMODE: 0x74, ENV: 0x78, HENV: 0x7C, ENVXO: 0x80 });

const A = (o) => APUST + o;
const bytesWat = (b) => Array.from(b, (x) => "\\" + (x & 0xff).toString(16).padStart(2, "0")).join("");
const i16le = (arr) => arr.flatMap((v) => [v & 0xff, (v >> 8) & 0xff]);
const i32le = (arr) => arr.flatMap((v) => [v & 0xff, (v >> 8) & 0xff, (v >> 16) & 0xff, (v >>> 24) & 0xff]);

/** The APU's constant data (IPL ROM, DSP tables). */
export function apuDataWat() {
  return [
    [A(APU_OFF.IPL), APU.iplrom],
    [A(APU_OFF.INITREGS), APU.dsp.initialRegs],
    [A(APU_OFF.GAUSS), i16le(APU.dsp.gauss)],
    [A(APU_OFF.RATES), i32le(APU.dsp.counterRates)],
    [A(APU_OFF.OFFSETS), i32le(APU.dsp.counterOffsets)],
  ].map(([at, b]) => `  (data (i32.const ${at}) "${bytesWat(b)}")\n`).join("");
}

const G = (names) => names.map((n) => `  (global $${n} (mut i32) (i32.const 0))`).join("\n") +
  "\n  (global $rs_frac (mut f32) (f32.const 0))";

/** Globals of the SMP, the DSP and the CPU<->APU clock. */
export function apuGlobalsWat() {
  return "\n" + G([
    // SMP registers, flags, the core's uint16 temporaries, the step state.
    "s_a", "s_x", "s_y", "s_sp", "s_pc",
    "s_fn", "s_fv", "s_fp", "s_fb", "s_fh", "s_fi", "s_fz", "s_fc",
    "s_rd", "s_wr", "s_dp", "s_tsp", "s_ya", "s_bit", "s_op", "s_ocyc",
    // SMP::clock (int32, runs while negative) and status ($F1-$F9).
    "s_clock", "s_iplen", "s_dspaddr", "s_f8", "s_f9",
    // Timers: enable, target, stage1/2/3 ticks.
    "t0_en", "t0_tg", "t0_s1", "t0_s2", "t0_s3",
    "t1_en", "t1_tg", "t1_s1", "t1_s2", "t1_s3",
    "t2_en", "t2_tg", "t2_s1", "t2_s2", "t2_s3",
    // DSP::clock and SPC_DSP state_t scalars.
    "d_clock", "d_phase", "d_eos", "d_kon", "d_newkon", "d_noise", "d_counter",
    "d_echooff", "d_echolen", "d_endxbuf", "d_envxbuf", "d_outxbuf",
    "d_tpmon", "d_tnon", "d_teon", "d_tdir", "d_tkoff", "d_tbrrnext", "d_tadsr0",
    "d_tbrrhdr", "d_tbrrbyte", "d_tsrcn", "d_tesa", "d_techoen", "d_tdiraddr",
    "d_tpitch", "d_toutput", "d_tlooped", "d_techoptr",
    "d_mo0", "d_mo1", "d_eo0", "d_eo1", "d_ei0", "d_ei1", "d_hpos",
    // CPU side (apu.cpp): reference position and remainder, in master clocks.
    "apu_ref", "apu_rem", "apu_nsmp", "apu_nout",
    // snes9x's Resampler (apu/resampler.h) when a per-title APU speedup
    // makes its time ratio differ from 1: ring start/end and the Hermite
    // history (r_frac is the f32 below).
    "rs_start", "rs_end", "rs_l0", "rs_l1", "rs_l2", "rs_l3", "rs_r0", "rs_r1", "rs_r2", "rs_r3",
  ]) + "\n";
}

// ---- small WAT helpers
const c = (v) => `(i32.const ${v})`;
const gg = (n) => `(global.get $${n})`;
const gs = (n, w) => `(global.set $${n} ${w})`;
const lg = (n) => `(local.get $${n})`;
const ls = (n, w) => `(local.set $${n} ${w})`;
const ram = (lay, a) => `(i32.add ${c(lay.ARAM)} ${a})`;
const reg = (r) => `(i32.load8_u ${c(A(APU_OFF.REGS) + r)})`;
const s8 = (w) => `(i32.extend8_s ${w})`;
const s16 = (w) => `(i32.extend16_s ${w})`;
// voice field: base in local $b
const vf = (o) => `(i32.add ${lg("b")} ${c(o)})`;
const vget = (o) => `(i32.load ${vf(o)})`;
const vset = (o, w) => `(i32.store ${vf(o)} ${w})`;
// voice register: base in local $r
const vreg = (o) => `(i32.load8_u (i32.add ${lg("r")} ${c(o)}))`;
const clamp16 = "(call $d_clamp16";

/** SMP timer tick (smp/timing.cpp Timer<freq>::tick), one clock or n. */
function timerWat(k, freq) {
  const p = `t${k}_`;
  return `
  (func $${p}tick
    (global.set $${p}s1 (i32.and (i32.add ${gg(p + "s1")} ${c(1)}) ${c(0xff)}))
    (if (i32.lt_u ${gg(p + "s1")} ${c(freq)}) (then (return)))
    ${gs(p + "s1", c(0))}
    (if (i32.eqz ${gg(p + "en")}) (then (return)))
    ${gs(p + "s2", `(i32.and (i32.add ${gg(p + "s2")} ${c(1)}) ${c(0xff)})`)}
    (if (i32.ne ${gg(p + "s2")} ${gg(p + "tg")}) (then (return)))
    ${gs(p + "s2", c(0))}
    ${gs(p + "s3", `(i32.and (i32.add ${gg(p + "s3")} ${c(1)}) ${c(15)})`)})
  (func $${p}tickn (param $n i32)
    (global.set $${p}s1 (i32.and (i32.add ${gg(p + "s1")} ${lg("n")}) ${c(0xff)}))
    (if (i32.lt_u ${gg(p + "s1")} ${c(freq)}) (then (return)))
    ${gs(p + "s1", `(i32.sub ${gg(p + "s1")} ${c(freq)})`)}
    (if (i32.eqz ${gg(p + "en")}) (then (return)))
    ${gs(p + "s2", `(i32.and (i32.add ${gg(p + "s2")} ${c(1)}) ${c(0xff)})`)}
    (if (i32.ne ${gg(p + "s2")} ${gg(p + "tg")}) (then (return)))
    ${gs(p + "s2", c(0))}
    ${gs(p + "s3", `(i32.and (i32.add ${gg(p + "s3")} ${c(1)}) ${c(15)})`)})`;
}

/** @param {import("./layout.js").SnesLayout} lay */
function smpWat(lay) {
  const R = (a) => ram(lay, a);
  const setp = [["fn", 0x80], ["fv", 0x40], ["fp", 0x20], ["fb", 0x10], ["fh", 0x08], ["fi", 0x04], ["fz", 0x02], ["fc", 0x01]];
  const temps = Array.from({ length: APU.opTemps }, (_, i) => `(local $t${i} i32)`).join(" ");
  // br_table dispatch: block k wraps blocks 0..k-1; opcode k's body follows block k.
  let disp = `(block $o0 (br_table ${Array.from({ length: 256 }, (_, i) => `$o${i}`).join(" ")} $o0 ${gg("s_op")}))`;
  for (let i = 0; i < 256; i++) {
    disp = `(block $o${i + 1}\n${disp}\n;; opcode $${i.toString(16).padStart(2, "0")}\n${APU.ops[i]}\n(return))`;
  }
  // The outermost block ($o256) is never targeted; the last opcode returns.
  return `
  (func $s_getp (result i32)
    ${setp.map(([f, b]) => `(i32.or (i32.shl ${gg("s_" + f)} ${c(Math.log2(b))})`).join(" ")} ${c(0)}${")".repeat(8)})
  (func $s_setp (param $v i32)
    ${setp.map(([f, b]) => gs("s_" + f, `(i32.ne (i32.and ${lg("v")} ${c(b)}) ${c(0)})`)).join("\n    ")})
  (func $s_setya (param $v i32)
    ${gs("s_a", `(i32.and ${lg("v")} ${c(0xff)})`)}
    ${gs("s_y", `(i32.and (i32.shr_u ${lg("v")} ${c(8)}) ${c(0xff)})`)})
${timerWat(0, 128)}
${timerWat(1, 128)}
${timerWat(2, 16)}
  ;; SMP::tick / tick(clocks): the three timers, SMP::clock and DSP::clock.
  (func $s_tick
    (call $t0_tick) (call $t1_tick) (call $t2_tick)
    ${gs("s_clock", `(i32.add ${gg("s_clock")} ${c(1)})`)}
    ${gs("d_clock", `(i32.add ${gg("d_clock")} ${c(1)})`)})
  (func $s_tickn (param $n i32)
    (call $t0_tickn ${lg("n")}) (call $t1_tickn ${lg("n")}) (call $t2_tickn ${lg("n")})
    ${gs("s_clock", `(i32.add ${gg("s_clock")} ${lg("n")})`)}
    ${gs("d_clock", `(i32.add ${gg("d_clock")} ${lg("n")})`)})

  ;; SMP::mmio_read ($F0-$FF).
  (func $s_mmio_read (param $a i32) (result i32)
    (local $v i32)
    (if (i32.eq ${lg("a")} ${c(0xf2)}) (then (return ${gg("s_dspaddr")})))
    (if (i32.eq ${lg("a")} ${c(0xf3)}) (then
      (call $d_sync)
      (return (i32.load8_u (i32.add ${c(A(APU_OFF.XREGS))} (i32.and ${gg("s_dspaddr")} ${c(0x7f)}))))))
    (if (i32.and (i32.ge_u ${lg("a")} ${c(0xf4)}) (i32.le_u ${lg("a")} ${c(0xf7)}))
      (then (return (i32.load8_u (i32.add ${c(A(APU_OFF.CPUREG))} (i32.and ${lg("a")} ${c(3)}))))))
    (if (i32.eq ${lg("a")} ${c(0xf8)}) (then (return ${gg("s_f8")})))
    (if (i32.eq ${lg("a")} ${c(0xf9)}) (then (return ${gg("s_f9")})))
    ${[0, 1, 2].map((k) => `(if (i32.eq ${lg("a")} ${c(0xfd + k)}) (then
      ${ls("v", `(i32.and ${gg(`t${k}_s3`)} ${c(15)})`)} ${gs(`t${k}_s3`, c(0))} (return ${lg("v")})))`).join("\n    ")}
    ${c(0)})

  ;; SMP::mmio_write ($F0-$FF).
  (func $s_mmio_write (param $a i32) (param $v i32)
    (if (i32.eq ${lg("a")} ${c(0xf1)}) (then
      ${gs("s_iplen", `(i32.ne (i32.and ${lg("v")} ${c(0x80)}) ${c(0)})`)}
      (if (i32.and ${lg("v")} ${c(0x20)}) (then
        (i32.store8 ${c(A(APU_OFF.CPUREG) + 3)} ${c(0)})
        (i32.store8 ${c(A(APU_OFF.CPUREG) + 2)} ${c(0)})))
      (if (i32.and ${lg("v")} ${c(0x10)}) (then
        (i32.store8 ${c(A(APU_OFF.CPUREG) + 1)} ${c(0)})
        (i32.store8 ${c(A(APU_OFF.CPUREG) + 0)} ${c(0)})))
      ${[2, 1, 0].map((k) => `(if (i32.and (i32.eqz ${gg(`t${k}_en`)}) (i32.ne (i32.and ${lg("v")} ${c(1 << k)}) ${c(0)}))
        (then ${gs(`t${k}_s2`, c(0))} ${gs(`t${k}_s3`, c(0))}))
      ${gs(`t${k}_en`, `(i32.ne (i32.and ${lg("v")} ${c(1 << k)}) ${c(0)})`)}`).join("\n      ")}
      (return)))
    (if (i32.eq ${lg("a")} ${c(0xf2)}) (then ${gs("s_dspaddr", lg("v"))} (return)))
    (if (i32.eq ${lg("a")} ${c(0xf3)}) (then
      (if (i32.and ${gg("s_dspaddr")} ${c(0x80)}) (then (return)))
      (call $d_sync)
      (call $d_write ${gg("s_dspaddr")} ${lg("v")})
      (return)))
    ;; $F4-$F7: SMP::port_write stores to apuram, which the op_write that
    ;; called us does anyway.
    (if (i32.eq ${lg("a")} ${c(0xf8)}) (then ${gs("s_f8", lg("v"))} (return)))
    (if (i32.eq ${lg("a")} ${c(0xf9)}) (then ${gs("s_f9", lg("v"))} (return)))
    (if (i32.eq ${lg("a")} ${c(0xfa)}) (then ${gs("t0_tg", lg("v"))} (return)))
    (if (i32.eq ${lg("a")} ${c(0xfb)}) (then ${gs("t1_tg", lg("v"))} (return)))
    (if (i32.eq ${lg("a")} ${c(0xfc)}) (then ${gs("t2_tg", lg("v"))} (return))))

  ;; SMP::op_read / op_write / op_readstack / op_writestack.
  (func $s_read (param $a i32) (result i32)
    (call $s_tick)
    (if (i32.eq (i32.and ${lg("a")} ${c(0xfff0)}) ${c(0xf0)}) (then (return (call $s_mmio_read ${lg("a")}))))
    (if (i32.and (i32.ge_u ${lg("a")} ${c(0xffc0)}) ${gg("s_iplen")})
      (then (return (i32.load8_u (i32.add ${c(A(APU_OFF.IPL))} (i32.and ${lg("a")} ${c(0x3f)}))))))
    (i32.load8_u ${R(lg("a"))}))
  (func $s_write (param $a i32) (param $v i32)
    (call $s_tick)
    (if (i32.eq (i32.and ${lg("a")} ${c(0xfff0)}) ${c(0xf0)}) (then (call $s_mmio_write ${lg("a")} ${lg("v")})))
    ;; all writes go to RAM, even MMIO writes
    (i32.store8 ${R(lg("a"))} ${lg("v")}))
  (func $s_readpc (result i32)
    (local $a i32)
    ${ls("a", gg("s_pc"))}
    ${gs("s_pc", `(i32.and (i32.add ${gg("s_pc")} ${c(1)}) ${c(0xffff)})`)}
    (call $s_read ${lg("a")}))
  (func $s_readstack (result i32)
    (call $s_tick)
    ${gs("s_sp", `(i32.and (i32.add ${gg("s_sp")} ${c(1)}) ${c(0xff)})`)}
    (i32.load8_u ${R(`(i32.or ${c(0x100)} ${gg("s_sp")})`)}))
  (func $s_writestack (param $v i32)
    (call $s_tick)
    (i32.store8 ${R(`(i32.or ${c(0x100)} ${gg("s_sp")})`)} ${lg("v")})
    ${gs("s_sp", `(i32.and (i32.sub ${gg("s_sp")} ${c(1)}) ${c(0xff)})`)})

  ;; algorithms.cpp (generated)
  ${Object.values(APU.functions).join("\n  ")}

  ;; SMP::op_step (generated opcode bodies; opcode_cycle kept).
  (func $smp_step ${temps}
    (if (i32.eqz ${gg("s_ocyc")}) (then ${gs("s_op", "(call $s_readpc)")}))
    ${gs("apu_nsmp", `(i32.add ${gg("apu_nsmp")} ${c(1)})`)}
    ${disp})

  ;; SMP::enter
  (func $smp_enter
    (block $d (loop $l
      (br_if $d (i32.ge_s ${gg("s_clock")} ${c(0)}))
      (call $smp_step)
      (br $l))))`;
}

/** @param {import("./layout.js").SnesLayout} lay */
function dspWat(lay) {
  const R = (a) => ram(lay, a);
  const VB = `(i32.add ${c(A(APU_OFF.VOICES))} (i32.shl ${lg("v")} ${c(8)}))`;
  const RB = `(i32.add ${c(A(APU_OFF.REGS))} (i32.shl ${lg("v")} ${c(4)}))`;
  const preDecl = "(local $b i32) (local $r i32)";
  const preInit = `${ls("b", VB)} ${ls("r", RB)}`;
  const vbit = `(i32.shl ${c(1)} ${lg("v")})`;
  const hist = (i, ch) => `(i32.add ${c(A(APU_OFF.HIST))} (i32.shl (i32.add (i32.shl (i32.add ${gg("d_hpos")} ${c(i)}) ${c(1)}) ${c(ch)}) ${c(2)}))`;
  const fir = (i, ch) => `(i32.shr_s (i32.mul (i32.load ${hist(i + 1, ch)}) ${s8(reg(0x0f + i * 0x10))}) ${c(6)})`;
  const echoPtr = (ch) => `(i32.and (i32.add ${gg("d_techoptr")} ${c(ch * 2)}) ${c(0xffff)})`;
  const get16 = (a) => `(i32.or (i32.load8_u ${R(a)}) (i32.shl (i32.load8_u ${R(`(i32.and (i32.add ${a} ${c(1)}) ${c(0xffff)})`)}) ${c(8)}))`;
  // run_counters / read_counter
  const readCounter = (rate) => `(i32.rem_u (i32.add ${gg("d_counter")} (i32.load (i32.add ${c(A(APU_OFF.OFFSETS))} (i32.shl ${rate} ${c(2)})))) (i32.load (i32.add ${c(A(APU_OFF.RATES))} (i32.shl ${rate} ${c(2)}))))`;
  const V1 = (v) => `(call $d_v1 ${c(v)})`, V2 = (v) => `(call $d_v2 ${c(v)})`,
    V3 = (v) => `(call $d_v3a ${c(v)}) (call $d_v3b ${c(v)}) (call $d_v3c ${c(v)})`,
    V3a = (v) => `(call $d_v3a ${c(v)})`, V3b = (v) => `(call $d_v3b ${c(v)})`, V3c = (v) => `(call $d_v3c ${c(v)})`,
    V4 = (v) => `(call $d_v4 ${c(v)})`, V5 = (v) => `(call $d_v5 ${c(v)})`, V6 = () => "(call $d_v6)",
    V7 = (v) => `(call $d_v7 ${c(v)})`, V8 = (v) => `(call $d_v8 ${c(v)})`, V9 = (v) => `(call $d_v9 ${c(v)})`;
  const V741 = (v) => `${V7(v)} ${V1(v + 3)} ${V4(v + 1)}`;
  const V852 = (v) => `${V8(v)} ${V5(v + 1)} ${V2(v + 2)}`;
  const V963 = (v) => `${V9(v)} ${V6(v + 1)} ${V3(v + 2)}`;
  const E = (n) => `(call $d_echo${n})`, M = (n) => `(call $d_misc${n})`;
  // GEN_DSP_TIMING, SPC_DSP.cpp
  const PH = [
    `${V5(0)} ${V2(1)}`, `${V6(0)} ${V3(1)}`, V741(0), V852(0), V963(0),
    V741(1), V852(1), V963(1), V741(2), V852(2), V963(2), V741(3), V852(3), V963(3),
    V741(4), V852(4), V963(4),
    `${V1(0)} ${V7(5)} ${V4(6)}`, V852(5), V963(5),
    `${V1(1)} ${V7(6)} ${V4(7)}`,
    `${V8(6)} ${V5(7)} ${V2(0)}`,
    `${V3a(0)} ${V9(6)} ${V6(7)} ${E(22)}`,
    `${V7(7)} ${E(23)}`, `${V8(7)} ${E(24)}`, `${V3b(0)} ${V9(7)} ${E(25)}`, E(26),
    `${M(27)} ${E(27)}`, `${M(28)} ${E(28)}`, `${M(29)} ${E(29)}`,
    `${M(30)} ${V3c(0)} ${E(30)}`, `${V4(0)} ${V1(2)}`,
  ];
  let phdisp = `(block $p0 (br_table ${Array.from({ length: 32 }, (_, i) => `$p${i}`).join(" ")} $p0 ${lg("p")}))`;
  for (let i = 0; i < 32; i++) phdisp = `(block $p${i + 1}\n${phdisp}\n${PH[i]}\n(br $next))`;
  const voiceOut = (ch) => `
    ${ls("amp", `(i32.shr_s (i32.mul ${gg("d_toutput")} ${s8(vreg(ch))}) ${c(7)})`)}
    ${gs(`d_mo${ch}`, `${clamp16} (i32.add ${gg(`d_mo${ch}`)} ${lg("amp")}))`)}
    (if (i32.and ${gg("d_teon")} ${vbit}) (then
      ${gs(`d_eo${ch}`, `${clamp16} (i32.add ${gg(`d_eo${ch}`)} ${lg("amp")}))`)}))`;
  const echoOutput = (ch) => `${clamp16} (i32.add
      ${s16(`(i32.shr_s (i32.mul ${gg(`d_mo${ch}`)} ${s8(reg(0x0c + ch * 0x10))}) ${c(7)})`)}
      ${s16(`(i32.shr_s (i32.mul ${gg(`d_ei${ch}`)} ${s8(reg(0x2c + ch * 0x10))}) ${c(7)})`)}))`;
  const echoRead = (ch) => `
    ${ls("s", `(i32.shr_s ${s16(get16(echoPtr(ch)))} ${c(1)})`)}
    (i32.store ${hist(0, ch)} ${lg("s")})
    (i32.store ${hist(8, ch)} ${lg("s")})`;
  const echoWrite = (ch) => `
    (if (i32.eqz (i32.and ${gg("d_techoen")} ${c(0x20)})) (then
      (i32.store8 ${R(echoPtr(ch))} ${gg(`d_eo${ch}`)})
      (i32.store8 ${R(`(i32.and (i32.add ${echoPtr(ch)} ${c(1)}) ${c(0xffff)})`)} (i32.shr_u ${gg(`d_eo${ch}`)} ${c(8)}))))
    ${gs(`d_eo${ch}`, c(0))}`;
  return `
  (func $d_clamp16 (param $x i32) (result i32)
    (if (result i32) (i32.eq ${s16(lg("x"))} ${lg("x")}) (then ${lg("x")})
      (else (i32.xor (i32.shr_s ${lg("x")} ${c(31)}) ${c(0x7fff)}))))

  ;; SPC_DSP::write (sdsp.hpp DSP::write synchronizes first; the caller does).
  (func $d_write (param $a i32) (param $v i32)
    (i32.store8 (i32.add ${c(A(APU_OFF.REGS))} ${lg("a")}) ${lg("v")})
    (i32.store8 (i32.add ${c(A(APU_OFF.XREGS))} ${lg("a")}) ${lg("v")})
    (if (i32.eq (i32.and ${lg("a")} ${c(0x0f)}) ${c(8)}) (then ${gs("d_envxbuf", lg("v"))}))
    (if (i32.eq (i32.and ${lg("a")} ${c(0x0f)}) ${c(9)}) (then ${gs("d_outxbuf", lg("v"))}))
    (if (i32.eq ${lg("a")} ${c(0x4c)}) (then ${gs("d_newkon", lg("v"))}))
    (if (i32.eq ${lg("a")} ${c(0x7c)}) (then
      ${gs("d_endxbuf", c(0))}
      (i32.store8 ${c(A(APU_OFF.REGS) + 0x7c)} ${c(0)}))))

  ;; DSP::synchronize: run the clocks the SMP has accumulated.
  (func $d_sync
    (if ${gg("d_clock")} (then (call $d_run ${gg("d_clock")}) ${gs("d_clock", c(0))})))

  (func $d_interp (param $v i32) (result i32)
    (local $b i32) (local $in i32) (local $off i32) (local $fwd i32) (local $rev i32) (local $out i32)
    ${ls("b", VB)}
    ${ls("in", `(i32.add ${lg("b")} (i32.shl (i32.add (i32.shr_s ${vget(V.IPOS)} ${c(12)}) ${vget(V.BUFPOS)}) ${c(2)}))`)}
    ${ls("off", `(i32.and (i32.shr_s ${vget(V.IPOS)} ${c(4)}) ${c(0xff)})`)}
    ${ls("fwd", `(i32.add ${c(A(APU_OFF.GAUSS))} (i32.shl (i32.sub ${c(255)} ${lg("off")}) ${c(1)}))`)}
    ${ls("rev", `(i32.add ${c(A(APU_OFF.GAUSS))} (i32.shl ${lg("off")} ${c(1)}))`)}
    ${ls("out", `(i32.shr_s (i32.mul (i32.load16_s ${lg("fwd")}) (i32.load ${lg("in")})) ${c(11)})`)}
    ${ls("out", `(i32.add ${lg("out")} (i32.shr_s (i32.mul (i32.load16_s offset=512 ${lg("fwd")}) (i32.load offset=4 ${lg("in")})) ${c(11)}))`)}
    ${ls("out", `(i32.add ${lg("out")} (i32.shr_s (i32.mul (i32.load16_s offset=512 ${lg("rev")}) (i32.load offset=8 ${lg("in")})) ${c(11)}))`)}
    ${ls("out", s16(lg("out")))}
    ${ls("out", `(i32.add ${lg("out")} (i32.shr_s (i32.mul (i32.load16_s ${lg("rev")}) (i32.load offset=12 ${lg("in")})) ${c(11)}))`)}
    (i32.and ${clamp16} ${lg("out")}) ${c(-2)}))

  (func $d_env (param $v i32)
    (local $b i32) (local $r i32) (local $env i32) (local $rate i32) (local $data i32) (local $mode i32)
    ${ls("b", VB)} ${ls("r", RB)}
    ${ls("env", vget(V.ENV))}
    (if (i32.eqz ${vget(V.EMODE)}) (then
      ${ls("env", `(i32.sub ${lg("env")} ${c(8)})`)}
      (if (i32.lt_s ${lg("env")} ${c(0)}) (then ${ls("env", c(0))}))
      ${vset(V.ENV, lg("env"))}
      (return)))
    ${ls("data", vreg(6))}
    (if (i32.and ${gg("d_tadsr0")} ${c(0x80)})
      (then
        (if (i32.ge_u ${vget(V.EMODE)} ${c(2)})
          (then
            ${ls("env", `(i32.sub ${lg("env")} ${c(1)})`)}
            ${ls("env", `(i32.sub ${lg("env")} (i32.shr_s ${lg("env")} ${c(8)}))`)}
            ${ls("rate", `(i32.and ${lg("data")} ${c(0x1f)})`)}
            (if (i32.eq ${vget(V.EMODE)} ${c(2)}) (then
              ${ls("rate", `(i32.add (i32.and (i32.shr_u ${gg("d_tadsr0")} ${c(3)}) ${c(0x0e)}) ${c(0x10)})`)})))
          (else
            ${ls("rate", `(i32.add (i32.shl (i32.and ${gg("d_tadsr0")} ${c(0x0f)}) ${c(1)}) ${c(1)})`)}
            ${ls("env", `(i32.add ${lg("env")} (if (result i32) (i32.lt_s ${lg("rate")} ${c(31)}) (then ${c(0x20)}) (else ${c(0x400)})))`)})))
      (else
        ${ls("data", vreg(7))}
        ${ls("mode", `(i32.shr_u ${lg("data")} ${c(5)})`)}
        (if (i32.lt_s ${lg("mode")} ${c(4)})
          (then ${ls("env", `(i32.mul ${lg("data")} ${c(0x10)})`)} ${ls("rate", c(31))})
          (else
            ${ls("rate", `(i32.and ${lg("data")} ${c(0x1f)})`)}
            (if (i32.eq ${lg("mode")} ${c(4)})
              (then ${ls("env", `(i32.sub ${lg("env")} ${c(0x20)})`)})
              (else (if (i32.lt_s ${lg("mode")} ${c(6)})
                (then
                  ${ls("env", `(i32.sub ${lg("env")} ${c(1)})`)}
                  ${ls("env", `(i32.sub ${lg("env")} (i32.shr_s ${lg("env")} ${c(8)}))`)})
                (else
                  ${ls("env", `(i32.add ${lg("env")} ${c(0x20)})`)}
                  (if (i32.and (i32.gt_s ${lg("mode")} ${c(6)}) (i32.ge_u ${vget(V.HENV)} ${c(0x600)}))
                    (then ${ls("env", `(i32.add ${lg("env")} ${c(0x8 - 0x20)})`)}))))))))))
    ;; Sustain level
    (if (i32.and (i32.eq (i32.shr_s ${lg("env")} ${c(8)}) (i32.shr_s ${lg("data")} ${c(5)})) (i32.eq ${vget(V.EMODE)} ${c(2)}))
      (then ${vset(V.EMODE, c(3))}))
    ${vset(V.HENV, lg("env"))}
    (if (i32.gt_u ${lg("env")} ${c(0x7ff)}) (then
      ${ls("env", `(if (result i32) (i32.lt_s ${lg("env")} ${c(0)}) (then ${c(0)}) (else ${c(0x7ff)}))`)}
      (if (i32.eq ${vget(V.EMODE)} ${c(1)}) (then ${vset(V.EMODE, c(2))}))))
    (if (i32.eqz ${readCounter(lg("rate"))}) (then ${vset(V.ENV, lg("env"))})))

  (func $d_brr (param $v i32)
    (local $b i32) (local $nyb i32) (local $hdr i32) (local $pos i32) (local $end i32)
    (local $s i32) (local $shift i32) (local $filter i32) (local $p1 i32) (local $p2 i32)
    ${ls("b", VB)}
    ${ls("nyb", `(i32.add (i32.mul ${gg("d_tbrrbyte")} ${c(0x100)}) (i32.load8_u ${R(`(i32.and (i32.add (i32.add ${vget(V.BRRADDR)} ${vget(V.BRROFF)}) ${c(1)}) ${c(0xffff)})`)}))`)}
    ${ls("hdr", gg("d_tbrrhdr"))}
    ${ls("pos", `(i32.add ${lg("b")} (i32.shl ${vget(V.BUFPOS)} ${c(2)}))`)}
    ${vset(V.BUFPOS, `(i32.add ${vget(V.BUFPOS)} ${c(4)})`)}
    (if (i32.ge_s ${vget(V.BUFPOS)} ${c(12)}) (then ${vset(V.BUFPOS, c(0))}))
    ${ls("end", `(i32.add ${lg("pos")} ${c(16)})`)}
    ${ls("shift", `(i32.shr_s ${lg("hdr")} ${c(4)})`)}
    ${ls("filter", `(i32.and ${lg("hdr")} ${c(0x0c)})`)}
    (block $d (loop $l
      (br_if $d (i32.ge_u ${lg("pos")} ${lg("end")}))
      ${ls("s", `(i32.shr_s ${s16(lg("nyb"))} ${c(12)})`)}
      (if (i32.le_s ${lg("shift")} ${c(12)})
        (then ${ls("s", `(i32.shr_s (i32.shl ${lg("s")} ${lg("shift")}) ${c(1)})`)})
        (else ${ls("s", `(i32.and ${lg("s")} ${c(~0x7ff)})`)}))
      ${ls("p1", `(i32.load offset=44 ${lg("pos")})`)}
      ${ls("p2", `(i32.shr_s (i32.load offset=40 ${lg("pos")}) ${c(1)})`)}
      (if (i32.ge_s ${lg("filter")} ${c(8)})
        (then
          ${ls("s", `(i32.add ${lg("s")} ${lg("p1")})`)}
          ${ls("s", `(i32.sub ${lg("s")} ${lg("p2")})`)}
          (if (i32.eq ${lg("filter")} ${c(8)})
            (then
              ${ls("s", `(i32.add ${lg("s")} (i32.shr_s ${lg("p2")} ${c(4)}))`)}
              ${ls("s", `(i32.add ${lg("s")} (i32.shr_s (i32.mul ${lg("p1")} ${c(-3)}) ${c(6)}))`)})
            (else
              ${ls("s", `(i32.add ${lg("s")} (i32.shr_s (i32.mul ${lg("p1")} ${c(-13)}) ${c(7)}))`)}
              ${ls("s", `(i32.add ${lg("s")} (i32.shr_s (i32.mul ${lg("p2")} ${c(3)}) ${c(4)}))`)})))
        (else (if ${lg("filter")} (then
          ${ls("s", `(i32.add ${lg("s")} (i32.shr_s ${lg("p1")} ${c(1)}))`)}
          ${ls("s", `(i32.add ${lg("s")} (i32.shr_s (i32.sub ${c(0)} ${lg("p1")}) ${c(5)}))`)}))))
      ${ls("s", `${clamp16} ${lg("s")})`)}
      ${ls("s", s16(`(i32.mul ${lg("s")} ${c(2)})`))}
      (i32.store offset=48 ${lg("pos")} ${lg("s")})
      (i32.store ${lg("pos")} ${lg("s")})
      ${ls("pos", `(i32.add ${lg("pos")} ${c(4)})`)}
      ${ls("nyb", `(i32.shl ${lg("nyb")} ${c(4)})`)}
      (br $l))))

  (func $d_misc27 ${gs("d_tpmon", `(i32.and ${reg(0x2d)} ${c(0xfe)})`)})
  (func $d_misc28 ${gs("d_tnon", reg(0x3d))} ${gs("d_teon", reg(0x4d))} ${gs("d_tdir", reg(0x5d))})
  (func $d_misc29
    ${gs("d_eos", `(i32.xor ${gg("d_eos")} ${c(1)})`)}
    (if ${gg("d_eos")} (then ${gs("d_newkon", `(i32.and ${gg("d_newkon")} (i32.xor ${gg("d_kon")} ${c(-1)}))`)})))
  (func $d_misc30
    (local $fb i32)
    (if ${gg("d_eos")} (then ${gs("d_kon", gg("d_newkon"))} ${gs("d_tkoff", `(i32.or ${reg(0x5c)} (i32.load8_u ${c(A(APU_OFF.MUTE))}))`)}))
    ;; run_counters
    ${gs("d_counter", `(i32.sub ${gg("d_counter")} ${c(1)})`)}
    (if (i32.lt_s ${gg("d_counter")} ${c(0)}) (then ${gs("d_counter", c(30720 - 1))}))
    ;; Noise
    (if (i32.eqz ${readCounter(`(i32.and ${reg(0x6c)} ${c(0x1f)})`)}) (then
      ${ls("fb", `(i32.xor (i32.shl ${gg("d_noise")} ${c(13)}) (i32.shl ${gg("d_noise")} ${c(14)}))`)}
      ${gs("d_noise", `(i32.xor (i32.and ${lg("fb")} ${c(0x4000)}) (i32.shr_s ${gg("d_noise")} ${c(1)}))`)})))

  (func $d_v1 (param $v i32) (local $r i32) ${ls("r", RB)}
    ${gs("d_tdiraddr", `(i32.and (i32.add (i32.mul ${gg("d_tdir")} ${c(0x100)}) (i32.mul ${gg("d_tsrcn")} ${c(4)})) ${c(0xffff)})`)}
    ${gs("d_tsrcn", vreg(4))})
  (func $d_v2 (param $v i32) (local $b i32) (local $r i32) (local $e i32) ${ls("b", VB)} ${ls("r", RB)}
    ${ls("e", gg("d_tdiraddr"))}
    (if (i32.eqz ${vget(V.KOND)}) (then ${ls("e", `(i32.and (i32.add ${lg("e")} ${c(2)}) ${c(0xffff)})`)}))
    ${gs("d_tbrrnext", get16(lg("e")))}
    ${gs("d_tadsr0", vreg(5))}
    ${gs("d_tpitch", vreg(2))})
  (func $d_v3a (param $v i32) (local $r i32) ${ls("r", RB)}
    ${gs("d_tpitch", `(i32.add ${gg("d_tpitch")} (i32.shl (i32.and ${vreg(3)} ${c(0x3f)}) ${c(8)}))`)})
  (func $d_v3b (param $v i32) (local $b i32) ${ls("b", VB)}
    ${gs("d_tbrrbyte", `(i32.load8_u ${R(`(i32.and (i32.add ${vget(V.BRRADDR)} ${vget(V.BRROFF)}) ${c(0xffff)})`)})`)}
    ${gs("d_tbrrhdr", `(i32.load8_u ${R(`(i32.and ${vget(V.BRRADDR)} ${c(0xffff)})`)})`)})
  (func $d_v3c (param $v i32) ${preDecl} (local $out i32) (local $kd i32) ${preInit}
    (if (i32.and ${gg("d_tpmon")} ${vbit}) (then
      ${gs("d_tpitch", `(i32.add ${gg("d_tpitch")} (i32.shr_s (i32.mul (i32.shr_s ${gg("d_toutput")} ${c(5)}) ${gg("d_tpitch")}) ${c(10)}))`)}))
    (if ${vget(V.KOND)} (then
      (if (i32.eq ${vget(V.KOND)} ${c(5)}) (then
        ${vset(V.BRRADDR, gg("d_tbrrnext"))}
        ${vset(V.BRROFF, c(1))}
        ${vset(V.BUFPOS, c(0))}
        ${gs("d_tbrrhdr", c(0))}))
      ${vset(V.ENV, c(0))}
      ${vset(V.HENV, c(0))}
      ${vset(V.IPOS, c(0))}
      ${ls("kd", `(i32.sub ${vget(V.KOND)} ${c(1)})`)}
      ${vset(V.KOND, lg("kd"))}
      (if (i32.and ${lg("kd")} ${c(3)}) (then ${vset(V.IPOS, c(0x4000))}))
      ${gs("d_tpitch", c(0))}))
    ${ls("out", `(call $d_interp ${lg("v")})`)}
    (if (i32.and ${gg("d_tnon")} ${vbit}) (then ${ls("out", s16(`(i32.mul ${gg("d_noise")} ${c(2)})`))}))
    ${gs("d_toutput", `(i32.and (i32.shr_s (i32.mul ${lg("out")} ${vget(V.ENV)}) ${c(11)}) ${c(-2)})`)}
    ${vset(V.ENVXO, `(i32.and (i32.shr_s ${vget(V.ENV)} ${c(4)}) ${c(0xff)})`)}
    (if (i32.or (i32.ne (i32.and ${reg(0x6c)} ${c(0x80)}) ${c(0)}) (i32.eq (i32.and ${gg("d_tbrrhdr")} ${c(3)}) ${c(1)}))
      (then ${vset(V.EMODE, c(0))} ${vset(V.ENV, c(0))}))
    (if ${gg("d_eos")} (then
      (if (i32.and ${gg("d_tkoff")} ${vbit}) (then ${vset(V.EMODE, c(0))}))
      (if (i32.and ${gg("d_kon")} ${vbit}) (then ${vset(V.KOND, c(5))} ${vset(V.EMODE, c(1))}))))
    (if (i32.eqz ${vget(V.KOND)}) (then (call $d_env ${lg("v")}))))
  (func $d_v4 (param $v i32) ${preDecl} (local $amp i32) ${preInit}
    ${gs("d_tlooped", c(0))}
    (if (i32.ge_s ${vget(V.IPOS)} ${c(0x4000)}) (then
      (call $d_brr ${lg("v")})
      ${vset(V.BRROFF, `(i32.add ${vget(V.BRROFF)} ${c(2)})`)}
      (if (i32.ge_s ${vget(V.BRROFF)} ${c(9)}) (then
        ${vset(V.BRRADDR, `(i32.and (i32.add ${vget(V.BRRADDR)} ${c(9)}) ${c(0xffff)})`)}
        (if (i32.and ${gg("d_tbrrhdr")} ${c(1)}) (then
          ${vset(V.BRRADDR, gg("d_tbrrnext"))}
          ${gs("d_tlooped", vbit)}))
        ${vset(V.BRROFF, c(1))}))))
    ${vset(V.IPOS, `(i32.add (i32.and ${vget(V.IPOS)} ${c(0x3fff)}) ${gg("d_tpitch")})`)}
    (if (i32.gt_s ${vget(V.IPOS)} ${c(0x7fff)}) (then ${vset(V.IPOS, c(0x7fff))}))
    ${voiceOut(0)})
  (func $d_v5 (param $v i32) ${preDecl} (local $amp i32) (local $e i32) ${preInit}
    ${voiceOut(1)}
    ${ls("e", `(i32.or ${reg(0x7c)} ${gg("d_tlooped")})`)}
    (if (i32.eq ${vget(V.KOND)} ${c(5)}) (then ${ls("e", `(i32.and ${lg("e")} (i32.xor ${vbit} ${c(-1)}))`)}))
    ${gs("d_endxbuf", `(i32.and ${lg("e")} ${c(0xff)})`)})
  (func $d_v6 ${gs("d_outxbuf", `(i32.and (i32.shr_s ${gg("d_toutput")} ${c(8)}) ${c(0xff)})`)})
  (func $d_v7 (param $v i32) (local $b i32) ${ls("b", VB)}
    (i32.store8 ${c(A(APU_OFF.REGS) + 0x7c)} ${gg("d_endxbuf")})
    (i32.store8 ${c(A(APU_OFF.XREGS) + 0x7c)} ${gg("d_endxbuf")})
    ${gs("d_envxbuf", vget(V.ENVXO))})
  (func $d_v8 (param $v i32)
    (i32.store8 (i32.add ${c(A(APU_OFF.REGS) + 9)} (i32.shl ${lg("v")} ${c(4)})) ${gg("d_outxbuf")})
    (i32.store8 (i32.add ${c(A(APU_OFF.XREGS) + 9)} (i32.shl ${lg("v")} ${c(4)})) ${gg("d_outxbuf")}))
  (func $d_v9 (param $v i32)
    (i32.store8 (i32.add ${c(A(APU_OFF.REGS) + 8)} (i32.shl ${lg("v")} ${c(4)})) ${gg("d_envxbuf")})
    (i32.store8 (i32.add ${c(A(APU_OFF.XREGS) + 8)} (i32.shl ${lg("v")} ${c(4)})) ${gg("d_envxbuf")}))

  (func $d_echo22 (local $s i32)
    ${gs("d_hpos", `(i32.add ${gg("d_hpos")} ${c(1)})`)}
    (if (i32.ge_s ${gg("d_hpos")} ${c(8)}) (then ${gs("d_hpos", c(0))}))
    ${gs("d_techoptr", `(i32.and (i32.add (i32.mul ${gg("d_tesa")} ${c(0x100)}) ${gg("d_echooff")}) ${c(0xffff)})`)}
    ${echoRead(0)}
    ${gs("d_ei0", fir(0, 0))}
    ${gs("d_ei1", fir(0, 1))})
  (func $d_echo23 (local $s i32)
    ${gs("d_ei0", `(i32.add ${gg("d_ei0")} (i32.add ${fir(1, 0)} ${fir(2, 0)}))`)}
    ${gs("d_ei1", `(i32.add ${gg("d_ei1")} (i32.add ${fir(1, 1)} ${fir(2, 1)}))`)}
    ${echoRead(1)})
  (func $d_echo24
    ${gs("d_ei0", `(i32.add ${gg("d_ei0")} (i32.add (i32.add ${fir(3, 0)} ${fir(4, 0)}) ${fir(5, 0)}))`)}
    ${gs("d_ei1", `(i32.add ${gg("d_ei1")} (i32.add (i32.add ${fir(3, 1)} ${fir(4, 1)}) ${fir(5, 1)}))`)})
  (func $d_echo25 (local $l i32) (local $r i32)
    ${ls("l", s16(`(i32.add ${gg("d_ei0")} ${fir(6, 0)})`))}
    ${ls("r", s16(`(i32.add ${gg("d_ei1")} ${fir(6, 1)})`))}
    ${ls("l", `(i32.add ${lg("l")} ${s16(fir(7, 0))})`)}
    ${ls("r", `(i32.add ${lg("r")} ${s16(fir(7, 1))})`)}
    ${gs("d_ei0", `(i32.and ${clamp16} ${lg("l")}) ${c(-2)})`)}
    ${gs("d_ei1", `(i32.and ${clamp16} ${lg("r")}) ${c(-2)})`)})
  (func $d_echo26 (local $l i32) (local $r i32)
    ${gs("d_mo0", echoOutput(0))}
    ${ls("l", `${clamp16} (i32.add ${gg("d_eo0")} ${s16(`(i32.shr_s (i32.mul ${gg("d_ei0")} ${s8(reg(0x0d))}) ${c(7)})`)}))`)}
    ${ls("r", `${clamp16} (i32.add ${gg("d_eo1")} ${s16(`(i32.shr_s (i32.mul ${gg("d_ei1")} ${s8(reg(0x0d))}) ${c(7)})`)}))`)}
    ${gs("d_eo0", `(i32.and ${lg("l")} ${c(-2)})`)}
    ${gs("d_eo1", `(i32.and ${lg("r")} ${c(-2)})`)})
  (func $d_echo27 (local $l i32) (local $r i32)
    ${ls("l", gg("d_mo0"))}
    ${ls("r", echoOutput(1))}
    ${gs("d_mo0", c(0))}
    ${gs("d_mo1", c(0))}
    (if (i32.and ${reg(0x6c)} ${c(0x40)}) (then ${ls("l", c(0))} ${ls("r", c(0))}))
    (call $apu_out ${lg("l")} ${lg("r")}))
  (func $d_echo28 ${gs("d_techoen", reg(0x6c))})
  (func $d_echo29
    ${gs("d_tesa", reg(0x6d))}
    (if (i32.eqz ${gg("d_echooff")}) (then ${gs("d_echolen", `(i32.mul (i32.and ${reg(0x7d)} ${c(0x0f)}) ${c(0x800)})`)}))
    ${gs("d_echooff", `(i32.add ${gg("d_echooff")} ${c(4)})`)}
    (if (i32.ge_s ${gg("d_echooff")} ${gg("d_echolen")}) (then ${gs("d_echooff", c(0))}))
    ${echoWrite(0)}
    ${gs("d_techoen", reg(0x6c))})
  (func $d_echo30 ${echoWrite(1)})

  ;; SPC_DSP::run: \`clocks\` phase bodies starting at m.phase.
  (func $d_run (param $n i32)
    (local $p i32)
    ${ls("p", gg("d_phase"))}
    ${gs("d_phase", `(i32.and (i32.add ${gg("d_phase")} ${lg("n")}) ${c(31)})`)}
    (block $done (loop $each
      (br_if $done (i32.le_s ${lg("n")} ${c(0)}))
      (block $next
${phdisp})
      ${ls("p", `(i32.and (i32.add ${lg("p")} ${c(1)}) ${c(31)})`)}
      ${ls("n", `(i32.sub ${lg("n")} ${c(1)})`)}
      (br $each))))`;
}

/**
 * The APU: SMP, DSP, and the CPU-side port functions the PPU register file
 * calls ($apu_read / $apu_write), the end-of-line hook and power-on.
 * @param {import("./layout.js").SnesLayout} lay
 */
export function apuWat(lay) {
  // Timings.APUSpeedup (a per-title fix): S9xAPUTimingSetSpeedup scales the
  // clock ratio's denominator by (256 - ticks) / 256 (integer division).
  const speed = lay.fixes?.apuSpeedup ?? 0;
  // APU_NUMERATOR / APU_DENOMINATOR, NTSC or PAL
  const num = lay.pal ? 34176 : 15664;
  const den = Math.floor(((lay.pal ? 709379 : 328125) * (256 - speed)) / 256);
  return smpWat(lay) + dspWat(lay) + `

  ;; One stereo sample into the host's ring.
  (func $apu_put (param $l i32) (param $r i32)
    (local $at i32)
    ${ls("at", `(i32.add ${c(AUDIO)} (i32.shl (i32.and ${gg("apu_nout")} ${c(AUDIO_FRAMES - 1)}) ${c(2)}))`)}
    (i32.store16 ${lg("at")} ${lg("l")})
    (i32.store16 offset=2 ${lg("at")} ${lg("r")})
    ${gs("apu_nout", `(i32.add ${gg("apu_nout")} ${c(1)})`)})

  ;; libretro snes9x hands the frame's samples to audio_batch_cb from
  ;; S9xSyncSpeed as vblank begins (the V=225 event), not when retro_run
  ;; returns: samples an instruction or DMA running past that point makes
  ;; belong to the next frame. So the ring's write cursor is published
  ;; here, not per sample.
${speed ? resamplerWat(lay, speed) : `
  ;; A DSP output sample (echo_27, SPC_DSP_OUT_HOOK). The resampler's time
  ;; ratio is 1 (SoundInputRate = SoundPlaybackRate = 32040), so snes9x
  ;; pulls the DSP stream as it is: straight into the host's ring.
  (func $apu_out (param $l i32) (param $r i32)
    (call $apu_put ${lg("l")} ${lg("r")})${lay.MSU != null ? `
    ;; SPC_DSP_OUT_HOOK's MSU-1 half (msu1.js)
    (call $msu_sample)` : ""})
  (func $apu_flush${lay.MSU != null ? `
    ;; with an MSU-1, S9xGetSampleCount / S9xMixSamples (msu1.js)
    (call $msu_flush))` : `
    (i32.store ${c(lay.ABI + 0x100)} (i32.and ${gg("apu_nout")} ${c(AUDIO_FRAMES - 1)})))`}`}

  ;; S9xAPUExecute: run the SMP up to CPU position $pos (master clocks from
  ;; the start of this scanline, snes9x's CPU.Cycles).
  (func $apu_sync (param $pos i32)
    (local $t i64)
    ${ls("t", `(i64.add (i64.mul (i64.const ${num}) (i64.extend_i32_s (i32.sub ${lg("pos")} ${gg("apu_ref")}))) (i64.extend_i32_u ${gg("apu_rem")}))`)}
    ${gs("s_clock", `(i32.sub ${gg("s_clock")} (i32.wrap_i64 (i64.div_s ${lg("t")} (i64.const ${den}))))`)}
    ${gs("apu_rem", `(i32.wrap_i64 (i64.rem_s (local.get $t) (i64.const ${den})))`)}
    (call $smp_enter)
    ${gs("apu_ref", lg("pos"))})

  ;; The CPU's position in master clocks from the start of the line.
  (func $apu_pos (result i32)
    (call $hnow))

  ;; S9xAPUReadPort / S9xAPUWritePort.
  (func $apu_read (param $p i32) (result i32)
    (call $apu_sync (call $apu_pos))
    (i32.load8_u (i32.add ${c(lay.ARAM + 0xf4)} (i32.and ${lg("p")} ${c(3)}))))
  (func $apu_write (param $p i32) (param $v i32)
    (call $apu_sync (call $apu_pos))
    ${gs("napuw", `(i32.add ${gg("napuw")} ${c(1)})`)}
    (i32.store8 (i32.add ${c(A(APU_OFF.CPUREG))} (i32.and ${lg("p")} ${c(3)})) ${lg("v")}))

  ;; The reference-time rebase at HC_HCOUNTER_MAX_EVENT (the line-end event
  ;; itself, S9xAPUEndScanline, is $apu_sync + $d_sync from $event_do):
  ;; positions in the next line count from 0 again.
  (func $apu_newline (param $hmax i32)
    ${gs("apu_ref", `(i32.sub ${gg("apu_ref")} ${lg("hmax")})`)})

  ;; S9xResetAPU: SMP::power, DSP::power (SPC_DSP::reset = load(initial_regs)).
  (func $apu_power
    (memory.fill ${c(lay.ARAM)} ${c(0)} ${c(0x10000)})
    (memory.fill ${c(A(APU_OFF.REGS))} ${c(0)} ${c(0x80)})
    (memory.copy ${c(A(APU_OFF.XREGS))} ${c(A(APU_OFF.INITREGS))} ${c(0x80)})
    (memory.fill ${c(A(APU_OFF.CPUREG))} ${c(0)} ${c(4)})
    (memory.fill ${c(A(APU_OFF.HIST))} ${c(0)} ${c(0x80)})
    (memory.fill ${c(A(APU_OFF.VOICES))} ${c(0)} ${c(0x800)})
    (i32.store8 ${c(A(APU_OFF.REGS) + 0x6c)} ${c(0xe0)})
    ${Array.from({ length: 8 }, (_, i) => `(i32.store ${c(A(APU_OFF.VOICES) + i * 0x100 + V.BRROFF)} ${c(1)})`).join(" ")}
    ${gs("s_pc", c(0xffc0))} ${gs("s_sp", c(0xef))}
    (call $s_setp ${c(0x02)})
    ${gs("s_iplen", c(1))}
    ${gs("d_noise", c(0x4000))} ${gs("d_eos", c(1))})`;
}

/**
 * snes9x's Resampler with a time ratio other than 1 (a per-title APU
 * speedup): the DSP pushes into a 2050-sample ring (S9xInitSound(32)), and
 * S9xSyncSpeed reads avail() samples through the 4-point Hermite
 * interpolator, in f32 as the C does.
 * @param {import("./layout.js").SnesLayout} lay
 * @param {number} ticks  Timings.APUSpeedup
 */
function resamplerWat(lay, ticks) {
  const size = RESAMP_SIZE;   // int16 samples (even)
  const step = Math.fround((32040 * 256) / (32040 * (256 - ticks)));
  const f = (v) => `(f32.const ${v})`;
  const filled = `(call $rs_filled)`;
  return `
  (func $rs_filled (result i32)
    (local $n i32)
    ${ls("n", `(i32.sub ${gg("rs_end")} ${gg("rs_start")})`)}
    (if (i32.lt_s ${lg("n")} ${c(0)}) (then ${ls("n", `(i32.add ${lg("n")} ${c(size)})`)}))
    ${lg("n")})
  ;; push_sample: dropped when fewer than 2 slots are free
  (func $apu_out (param $l i32) (param $r i32)
    (if (i32.lt_s (i32.sub ${c(size - 2)} ${filled}) ${c(2)}) (then (return)))
    (i32.store16 (i32.add ${c(RESAMP)} (i32.shl ${gg("rs_end")} ${c(1)})) ${lg("l")})
    (i32.store16 (i32.add ${c(RESAMP + 2)} (i32.shl ${gg("rs_end")} ${c(1)})) ${lg("r")})
    ${gs("rs_end", `(i32.rem_u (i32.add ${gg("rs_end")} ${c(2)}) ${c(size)})`)})
  ;; hermite(mu1, a, b, c, d)
  (func $rs_herm (param $mu1 f32) (param $a f32) (param $b f32) (param $c f32) (param $d f32) (result f32)
    (local $mu2 f32) (local $mu3 f32) (local $m0 f32) (local $m1 f32)
    (local.set $mu2 (f32.mul (local.get $mu1) (local.get $mu1)))
    (local.set $mu3 (f32.mul (local.get $mu2) (local.get $mu1)))
    (local.set $m0 (f32.mul (f32.sub (local.get $c) (local.get $a)) ${f(0.5)}))
    (local.set $m1 (f32.mul (f32.sub (local.get $d) (local.get $b)) ${f(0.5)}))
    (f32.add (f32.add (f32.add
      (f32.mul (f32.add (f32.sub (f32.mul ${f(2)} (local.get $mu3)) (f32.mul ${f(3)} (local.get $mu2))) ${f(1)}) (local.get $b))
      (f32.mul (f32.add (f32.sub (local.get $mu3) (f32.mul ${f(2)} (local.get $mu2))) (local.get $mu1)) (local.get $m0)))
      (f32.mul (f32.sub (local.get $mu3) (local.get $mu2)) (local.get $m1)))
      (f32.mul (f32.add (f32.mul ${f(-2)} (local.get $mu3)) (f32.mul ${f(3)} (local.get $mu2))) (local.get $c))))
  ;; short_clamp((int)v)
  (func $rs_clamp (param $v f32) (result i32)
    (local $n i32)
    (local.set $n (i32.trunc_sat_f32_s (local.get $v)))
    (if (result i32) (i32.ne (i32.extend16_s (local.get $n)) (local.get $n))
      (then (i32.xor (i32.shr_s (local.get $n) (i32.const 31)) (i32.const 0x7fff)))
      (else (local.get $n))))
  ;; S9xSyncSpeed: avail() = trunc(((filled >> 1) - r_frac) / r_step) * 2,
  ;; then read(avail) into the host's ring.
  (func $apu_flush
    (local $want i32) (local $o i32) (local $sl i32) (local $sr i32)
    ${ls("want", `(i32.shl (i32.trunc_sat_f32_s (f32.div (f32.sub (f32.convert_i32_s (i32.shr_s ${filled} ${c(1)})) (global.get $rs_frac)) ${f(step)})) ${c(1)})`)}
    (block $done (loop $outer
      (br_if $done (i32.ge_s ${lg("o")} ${lg("want")}))
      (br_if $done (i32.lt_s ${filled} ${c(2)}))
      ${ls("sl", `(i32.load16_s (i32.add ${c(RESAMP)} (i32.shl ${gg("rs_start")} ${c(1)})))`)}
      ${ls("sr", `(i32.load16_s (i32.add ${c(RESAMP + 2)} (i32.shl ${gg("rs_start")} ${c(1)})))`)}
      (block $inner_done (loop $inner
        (br_if $inner_done (f32.gt (global.get $rs_frac) ${f(1)}))
        (br_if $inner_done (i32.ge_s ${lg("o")} ${lg("want")}))
        (call $apu_put
          (call $rs_clamp (call $rs_herm (global.get $rs_frac) (f32.convert_i32_s ${gg("rs_l0")}) (f32.convert_i32_s ${gg("rs_l1")}) (f32.convert_i32_s ${gg("rs_l2")}) (f32.convert_i32_s ${gg("rs_l3")})))
          (call $rs_clamp (call $rs_herm (global.get $rs_frac) (f32.convert_i32_s ${gg("rs_r0")}) (f32.convert_i32_s ${gg("rs_r1")}) (f32.convert_i32_s ${gg("rs_r2")}) (f32.convert_i32_s ${gg("rs_r3")}))))
        ${ls("o", `(i32.add ${lg("o")} ${c(2)})`)}
        (global.set $rs_frac (f32.add (global.get $rs_frac) ${f(step)}))
        (br $inner)))
      (if (f32.gt (global.get $rs_frac) ${f(1)})
        (then
          ${gs("rs_l0", gg("rs_l1"))} ${gs("rs_l1", gg("rs_l2"))} ${gs("rs_l2", gg("rs_l3"))} ${gs("rs_l3", lg("sl"))}
          ${gs("rs_r0", gg("rs_r1"))} ${gs("rs_r1", gg("rs_r2"))} ${gs("rs_r2", gg("rs_r3"))} ${gs("rs_r3", lg("sr"))}
          (global.set $rs_frac (f32.sub (global.get $rs_frac) ${f(1)}))
          ${gs("rs_start", `(i32.add ${gg("rs_start")} ${c(2)})`)}
          (if (i32.ge_s ${gg("rs_start")} ${c(size)}) (then ${gs("rs_start", `(i32.sub ${gg("rs_start")} ${c(size)})`)}))))
      (br $outer)))
    (i32.store ${c(lay.ABI + 0x100)} (i32.and ${gg("apu_nout")} ${c(AUDIO_FRAMES - 1)})))`;
}
